/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/**
 * The two status groups the filter vocabulary understands alongside the six
 * literal statuses (ADR 0009). `open` is every status that is not closed.
 */
export type IssueStatusGroup = "open" | "closed";

export const ISSUE_STATUS_GROUPS: readonly IssueStatusGroup[] = [
  "open",
  "closed",
];

/** Expands one status-or-group token to the literal statuses it names; an
 *  unrecognised token expands to nothing. */
export function expandIssueStatusToken(
  token: string,
): readonly IssueStatus[] {
  if (token === "open") {
    return ISSUE_STATUSES.filter(
      (status) => !CLOSED_ISSUE_STATUSES.includes(status),
    );
  }
  if (token === "closed") {
    return CLOSED_ISSUE_STATUSES;
  }
  return ISSUE_STATUSES.includes(token as IssueStatus)
    ? [token as IssueStatus]
    : [];
}

/** Expands a list of status-or-group tokens to the deduplicated literal
 *  statuses they name, preserving first-seen order. */
export function expandIssueStatusTokens(
  tokens: readonly string[],
): readonly IssueStatus[] {
  const seen = new Set<IssueStatus>();
  for (const token of tokens) {
    for (const status of expandIssueStatusToken(token)) {
      seen.add(status);
    }
  }
  return [...seen];
}

