const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Resolves a `due_before` filter value (ADR 0009) to the exclusive-upper-bound
 * instant the repository filters on. A calendar date (`YYYY-MM-DD`) includes
 * the whole day, so the cutoff is midnight UTC of the *next* day; a full
 * timestamp is already an exclusive cutoff and passes through unchanged.
 */
export function resolveDueBeforeCutoff(value: string): IsoTimestamp {
  if (CALENDAR_DATE.test(value)) {
    const startOfDay = new Date(`${value}T00:00:00.000Z`).getTime();
    return toIsoTimestamp(new Date(startOfDay + DAY_MS));
  }
  return toIsoTimestamp(new Date(value));
}

