  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

input.new_string:
export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  // `assigneeId`/`authorId` of `"me"` travel unresolved through the URL and
  // the schema; the service is where "me" becomes the acting user, so an API
  // caller and a page asking the same question get the same answer.
  return issueRepo.listIssues({
    ...input,
    assigneeId:
      input.assigneeId === "me"
        ? actor.userId
        : (input.assigneeId as IssueId extends never ? never : typeof input.assigneeId),
    authorId: input.authorId === "me" ? actor.userId : input.authorId,
  } as IssueFilterInput);
}

