/**
 * `assigneeId`/`authorId` of `"me"` must be resolved against the acting user
 * before reaching the repository (`issueService.listIssues` does this) — the
 * repository has no actor to resolve it against.
 */
function resolveUserFilter<T extends UserId | "me" | null | undefined>(
  value: T,
): Exclude<T, "me"> {
  if (value === "me") {
    throw new Error(
      "Unresolved 'me' filter value reached the issue repository.",
    );
  }
  return value as Exclude<T, "me">;
}

/** Builds the shared predicate list behind `listIssues` and its count. */
function issueFilters(input: IssueFilterInput): readonly SQL[] {
  const archivedOnly = input.archivedOnly === true;
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  return compact(
    orgPredicate(issues.orgId, input.orgId),
    archivedOnly
      ? isNotNull(issues.archivedAt)
      : livePredicate(issues.archivedAt, scope),
    input.projectId === undefined
      ? undefined
      : eq(issues.projectId, input.projectId),
    input.status === undefined || input.status.length === 0
      ? undefined
      : inArray(issues.status, [...input.status]),
    input.priority === undefined || input.priority.length === 0
      ? undefined
      : inArray(issues.priority, [...input.priority]),
    // `undefined` arrives from the "Anyone" option of the filter bar, and
    // narrows nothing; `null` is the sanctioned spelling of "Unassigned" and
    // must still narrow the list to rows with no assignee at all.
    (() => {
      const assigneeId = resolveUserFilter(input.assigneeId);
      return assigneeId === undefined
        ? undefined
        : assigneeId === null
          ? isNull(issues.assigneeId)
          : eq(issues.assigneeId, assigneeId);
    })(),
    (() => {
      const authorId = resolveUserFilter(input.authorId);
      return authorId === undefined
        ? undefined
        : eq(issues.authorId, authorId);
    })(),
    input.dueBefore === undefined
      ? undefined
      : lt(issues.dueAt, resolveDueBeforeCutoff(input.dueBefore)),
