import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("scratch-check");
});

afterAll(() => {
  cleanup();
});

async function insertIssue(overrides: Partial<{ title: string; assigneeId: any; dueAt: any }> = {}) {
  const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
  return issueRepo.insertIssue(
    issueInput(north.org.id, north.project.id, overrides),
    north.userIds.owner,
    number,
  );
}

describe("scratch filter checks", () => {
  it("unassigned filter only matches issues with no assignee", async () => {
    await insertIssue({ title: "Assigned", assigneeId: north.userIds.member });
    const unassigned = await insertIssue({ title: "Unassigned one", assigneeId: null });

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      assigneeId: null,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((i) => i.id)).toContain(unassigned.id);
    expect(page.items.every((i) => i.assigneeId === null)).toBe(true);
  });

  it("label filter is all-of, not any-of", async () => {
    const labelA = await labelRepo.insertLabel({ orgId: north.org.id, name: "bug-a", color: "#111111", description: null });
    const labelB = await labelRepo.insertLabel({ orgId: north.org.id, name: "bug-b", color: "#222222", description: null });

    const both = await insertIssue({ title: "Has both" });
    await issueRepo.updateIssue({ orgId: north.org.id, issueId: both.id, labelIds: [labelA.id, labelB.id] });

    const onlyA = await insertIssue({ title: "Has only A" });
    await issueRepo.updateIssue({ orgId: north.org.id, issueId: onlyA.id, labelIds: [labelA.id] });

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      labelIds: [labelA.id, labelB.id],
      limit: 25,
      cursor: null,
    });

    const ids = page.items.map((i) => i.id);
    expect(ids).toContain(both.id);
    expect(ids).not.toContain(onlyA.id);
    expect(page.total).toBe(1);
  });

  it("due_before calendar date includes the whole day; full timestamp is strict", async () => {
    const dueOnDay = await insertIssue({ title: "Due midday", dueAt: "2026-05-10T12:00:00.000Z" });
    const dueNextDay = await insertIssue({ title: "Due next day", dueAt: "2026-05-11T01:00:00.000Z" });

    const byDate = await issueRepo.listIssues({
      orgId: north.org.id,
      dueBefore: "2026-05-10",
      limit: 25,
      cursor: null,
    });
    const dateIds = byDate.items.map((i) => i.id);
    expect(dateIds).toContain(dueOnDay.id);
    expect(dateIds).not.toContain(dueNextDay.id);

    const byTimestamp = await issueRepo.listIssues({
      orgId: north.org.id,
      dueBefore: "2026-05-10T12:00:00.000Z",
      limit: 25,
      cursor: null,
    });
    expect(byTimestamp.items.map((i) => i.id)).not.toContain(dueOnDay.id);
  });

  it("archivedOnly lists archived issues and nothing else", async () => {
    const live = await insertIssue({ title: "Live one" });
    const archived = await insertIssue({ title: "Archived one" });
    await issueRepo.archiveIssue(north.org.id, archived.id);

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      archivedOnly: true,
      limit: 25,
      cursor: null,
    });

    const ids = page.items.map((i) => i.id);
    expect(ids).toContain(archived.id);
    expect(ids).not.toContain(live.id);
  });

  it("status group 'open' expands to the non-closed statuses", async () => {
    const { expandIssueStatusTokens } = await import("@/types/issue");
    expect(expandIssueStatusTokens(["open"])).toEqual([
      "backlog",
      "todo",
      "in_progress",
      "in_review",
    ]);
    expect(expandIssueStatusTokens(["closed"])).toEqual(["done", "canceled"]);
  });
});

