import { describe, expect, it } from "vitest";
import { exportIssuesSchema } from "@/schemas/export";
import { issueFilterSchema } from "@/schemas/issue";

describe("scratch: status group + me in schemas", () => {
  it("issueFilterSchema expands status=open and refuses unknown statuses", () => {
    const parsed = issueFilterSchema.parse({
      orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
      status: ["open"],
      assigneeId: "me",
      authorId: "me",
    });
    expect(parsed.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(parsed.assigneeId).toBe("me");
    expect(parsed.authorId).toBe("me");

    expect(() =>
      issueFilterSchema.parse({
        orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
        status: ["nonsense"],
      }),
    ).toThrow();
  });

  it("exportIssuesSchema accepts status=open the same way", () => {
    const parsed = exportIssuesSchema.parse({
      orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
      status: ["open"],
    });
    expect(parsed.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
  });

  it("issueFilterSchema accepts a calendar date for due_before", () => {
    const parsed = issueFilterSchema.parse({
      orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
      dueBefore: "2026-05-10",
    });
    expect(parsed.dueBefore).toBe("2026-05-10");
  });
});

